22	void IASTColumnsTransformer::transform(const ASTPtr & transformer, ASTs & nodes)
23	{
24	    if (const auto * apply = transformer->as<ASTColumnsApplyTransformer>())
25	    {
26	        apply->transform(nodes);
27	    }
28	    else if (const auto * except = transformer->as<ASTColumnsExceptTransformer>())
29	    {
30	        except->transform(nodes);
