61	void ASTColumnsApplyTransformer::transform(ASTs & nodes) const
62	{
63	    for (auto & column : nodes)
64	    {
65	        String name;
66	        auto alias = column->tryGetAlias();
67	        if (!alias.empty())
68	            name = alias;
69	        else
70	        {
71	            if (const auto * id = column->as<ASTIdentifier>())
72	                name = id->shortName();
73	            else
74	                name = column->getColumnName();
75	        }
76	        if (lambda)
77	        {
78	            auto body = lambda->as<const ASTFunction &>().arguments->children.at(1)->clone();
79	            std::stack<ASTPtr> stack;
80	            stack.push(body);
81	            while (!stack.empty())
82	            {
83	                auto ast = stack.top();
84	                stack.pop();
85	                for (auto & child : ast->children)
86	                {
87	                    if (auto arg_name = tryGetIdentifierName(child); arg_name && arg_name == lambda_arg)
88	                    {
89	                        child = column->clone();
90	                        continue;
91	                    }
92	                    stack.push(child);
93	                }
94	            }
95	            column = body;
96	        }
97	        else
98	        {
99	            auto function = makeASTFunction(func_name, column);
100	            function->parameters = parameters;
101	            column = function;
102	        }
103	        if (!column_name_prefix.empty())
104	            column->setAlias(column_name_prefix + name);
105	    }
106	}
