206	void ASTColumnsExceptTransformer::transform(ASTs & nodes) const
207	{
208	    std::set<String> expected_columns;
209	    if (original_pattern.empty())
210	    {
211	        for (const auto & child : children)
212	            expected_columns.insert(child->as<const ASTIdentifier &>().name());
213	
214	        for (auto it = nodes.begin(); it != nodes.end();)
215	        {
216	            if (const auto * id = it->get()->as<ASTIdentifier>())
217	            {
218	                auto expected_column = expected_columns.find(id->shortName());
219	                if (expected_column != expected_columns.end())
220	                {
221	                    expected_columns.erase(expected_column);
222	                    it = nodes.erase(it);
223	                    continue;
224	                }
225	            }
226	            ++it;
227	        }
228	    }
229	    else
230	    {
231	        for (auto it = nodes.begin(); it != nodes.end();)
232	        {
233	            if (const auto * id = it->get()->as<ASTIdentifier>())
234	            {
235	                if (isColumnMatching(id->shortName()))
236	                {
237	                    it = nodes.erase(it);
238	                    continue;
239	                }
240	            }
241	            ++it;
242	        }
243	    }
244	
245	    if (is_strict && !expected_columns.empty())
246	    {
247	        String expected_columns_str;
248	        std::for_each(expected_columns.begin(), expected_columns.end(),
249	            [&](String x) { expected_columns_str += (" " + x) ; });
250	
251	        throw Exception(
252	            "Columns transformer EXCEPT expects following column(s) :" + expected_columns_str,
253	            ErrorCodes::NO_SUCH_COLUMN_IN_TABLE);
254	    }
255	}
