257	void ASTColumnsExceptTransformer::setPattern(String pattern)
258	{
259	    original_pattern = std::move(pattern);
260	    column_matcher = std::make_shared<RE2>(original_pattern, RE2::Quiet);
261	    if (!column_matcher->ok())
262	        throw DB::Exception(
263	            "COLUMNS pattern " + original_pattern + " cannot be compiled: " + column_matcher->error(),
264	            DB::ErrorCodes::CANNOT_COMPILE_REGEXP);
265	}
