339	void ASTColumnsReplaceTransformer::replaceChildren(ASTPtr & node, const ASTPtr & replacement, const String & name)
340	{
341	    for (auto & child : node->children)
342	    {
343	        if (const auto * id = child->as<ASTIdentifier>())
344	        {
345	            if (id->shortName() == name)
346	                child = replacement->clone();
347	        }
348	        else
349	            replaceChildren(child, replacement, name);
350	    }
351	}
